import XCTest
@testable import BarPathKit

/// W46 "vs last time": parity with tools/barpath/result_compare.py on result_compare_cases.json
/// (generated by tools/tests/test_result_compare.py; invented data), plus the Swift-only glue.
final class ResultCompareTests: XCTestCase {

    private func score(_ obj: [String: Any]) throws -> ResultScore {
        let defObj = try XCTUnwrap(obj["definition"] as? [String: Any])
        let defData: Data = try JSONSerialization.data(withJSONObject: defObj, options: [])
        let def: WorkoutDefinition = try JSONDecoder().decode(WorkoutDefinition.self, from: defData)
        let total: Double = try XCTUnwrap((obj["totalSeconds"] as? NSNumber)?.doubleValue)
        return ResultScore(definition: def, totalSeconds: total,
                           finished: (obj["finished"] as? Bool) ?? false,
                           capped: (obj["capped"] as? Bool) ?? false,
                           repsAtCap: (obj["repsAtCap"] as? NSNumber)?.intValue,
                           rounds: (obj["rounds"] as? NSNumber)?.intValue,
                           extraReps: (obj["extraReps"] as? NSNumber)?.intValue,
                           roundSize: (obj["roundSize"] as? NSNumber)?.intValue,
                           rx: obj["rx"] as? Bool)
    }

    func testParityWithPythonReference() throws {
        let data: Data = try fixtureData("result_compare_cases", "json")
        let root = try XCTUnwrap(try JSONSerialization.jsonObject(with: data) as? [String: Any])
        let cases = try XCTUnwrap(root["cases"] as? [[String: Any]])
        XCTAssertGreaterThanOrEqual(cases.count, 25)
        for c in cases {
            let name: String = (c["name"] as? String) ?? "?"
            let current: ResultScore = try score(try XCTUnwrap(c["current"] as? [String: Any]))
            var previous: ResultScore? = nil
            if let p = c["previous"] as? [String: Any] {
                previous = try score(p)
            }
            let got: ResultCompare.Comparison? = ResultCompare.compare(current: current, previous: previous)
            if let expected = c["expected"] as? [String: Any] {
                let g = try XCTUnwrap(got, name)
                XCTAssertEqual(g.kind.rawValue, expected["kind"] as? String, name)
                XCTAssertEqual(g.text, expected["text"] as? String, name)
                XCTAssertEqual(g.tone.rawValue, expected["tone"] as? String, name)
            } else {
                XCTAssertNil(got, name)
            }
        }
    }

    // MARK: - Swift glue

    private func seg(_ kind: SegmentKind, _ movement: String, _ value: Double, _ unit: TargetUnit) -> WorkoutSegment {
        return WorkoutSegment(kind: kind, movement: movement, name: movement, target: SegmentTarget(value, unit))
    }

    /// Invented 3 rounds for time, 5:00 cap: 10 pull-ups, 20 push-ups, 30 squats, 1:00 rest.
    private func cappedResult(repsAtCap: Int?, run: Bool = false) -> WorkoutResult {
        var one: [WorkoutSegment] = [seg(.station, "pullUps", 10, .reps), seg(.station, "pushUps", 20, .reps),
                                     seg(.station, "airSquats", 30, .reps), seg(.rest, "rest", 60, .seconds)]
        if run { one[0] = seg(.run, "run", 200, .meters) }
        let def = WorkoutDefinition(id: "test.fortime", name: "T", shortName: "T", format: .forTime, team: .solo,
                                    timeCapSeconds: 300, healthKitActivity: "crossTraining",
                                    segments: one + one + one, roundSize: 4)
        let t0: Double = 1_800_000_000
        let bounds: [(Double, Double)] = [(0, 60), (60, 150), (150, 280), (280, 340), (340, 400), (400, 520)]
        var segs: [SegmentResult] = []
        for (i, b) in bounds.enumerated() {
            segs.append(SegmentResult(index: i, kind: def.segments[i].kind, movement: def.segments[i].movement,
                                      title: "t", start: t0 + b.0, end: t0 + b.1, duration: b.1 - b.0))
        }
        let start = Date(timeIntervalSince1970: t0)
        return WorkoutResult(definition: def, startDate: start, finishDate: nil,
                             endDate: start.addingTimeInterval(520), totalSeconds: 520,
                             segments: segs, events: [], repsAtCap: repsAtCap)
    }

    /// Same numbers as test_reps_done_at_cap in Python.
    func testRepsDoneAtCap() {
        XCTAssertEqual(ResultCompare.repsDoneAtCap(cappedResult(repsAtCap: 0)), 60)
        XCTAssertEqual(ResultCompare.repsDoneAtCap(cappedResult(repsAtCap: 7)), 67)
        XCTAssertNil(ResultCompare.repsDoneAtCap(cappedResult(repsAtCap: nil)))
        XCTAssertNil(ResultCompare.repsDoneAtCap(cappedResult(repsAtCap: 7, run: true)))
    }

    func testCountText() {
        XCTAssertEqual(ResultCompare.count(1, "round"), "+1 round")
        XCTAssertEqual(ResultCompare.count(-3, "rep"), "\u{2212}3 reps")
        XCTAssertEqual(ResultCompare.count(0, "rep"), "+0 reps")
    }

    /// The app path: a stored AMRAP result against itself with one fewer round.
    func testScoreFromStoredAmrap() throws {
        let r: WorkoutResult = try WorkoutResult.decode(from: try fixtureData("workout-amrap-2026-10-30", "json"))
        let summary: WorkoutSummary = WorkoutSummary.make(result: r, previous: nil, maxHeartRate: nil)
        let s: ResultScore = ResultScore.make(result: r, summary: summary)
        XCTAssertEqual(s.rounds, summary.headline.rounds)
        XCTAssertEqual(s.extraReps, summary.headline.extraReps)
        XCTAssertFalse(s.capped)
        XCTAssertNil(s.repsAtCap)
        guard let rounds = s.rounds, rounds >= 1 else { return }
        let earlier = ResultScore(definition: s.definition, totalSeconds: s.totalSeconds, finished: s.finished,
                                  rounds: rounds - 1, extraReps: s.extraReps, roundSize: s.roundSize)
        let c = try XCTUnwrap(ResultCompare.compare(current: s, previous: earlier))
        XCTAssertEqual(c.kind, ResultCompare.Kind.amrap)
        XCTAssertEqual(c.tone, ResultCompare.Tone.better)
        XCTAssertTrue(c.text.hasPrefix("+"))
        // No earlier result, or the same result: nothing.
        XCTAssertNil(ResultScore.comparison(result: r, summary: summary, previous: nil, maxHeartRate: nil))
        XCTAssertNil(ResultScore.comparison(result: r, summary: summary, previous: r, maxHeartRate: nil))
    }
}
